use super::{client::{Control, Reply}, process::Process, protocol::{Command, Empty, Frame, Id, Request, Session}, routes::Route};
use super::super::{config::Agentd, BackendStatus, BackendError};
use parking_lot::Mutex;
use std::{collections::HashMap, sync::Arc, time::{Duration, Instant}};
use tokio::sync::mpsc;
use serde_json::{Value, json};
struct Pending { reply: Option<Reply>, since: Instant, ping: bool }
struct State {
    config: Agentd,
    status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>,
    routes: HashMap<String, Route>,
    pending: HashMap<Id, Pending>,
    deferred: Vec<(Command, Reply, Instant)>,
    counter: u64,
    failures: u32,
    next_start: Instant,
    last_ping: Instant,
    started: Instant,
    last_used: Instant,
    stopping: bool,
}
impl State {
    fn request(&mut self, process: &Process, command: Command, reply: Option<Reply>) -> anyhow::Result<()> {
        let ping = matches!(command, Command::Ping(_));
        self.counter += 1;
        let id = Id::Text(format!("rust-{}", self.counter));
        process.write(&Request { id: id.clone(), command }, self.config.max_line_bytes)?;
        self.pending.insert(id, Pending { reply, since: Instant::now(), ping });
        Ok(())
    }
    fn fail(&mut self, error: String) {
        self.failures = self.failures.saturating_add(1);
        let circuit = error.contains("AgentdProtocolMismatch") || self.failures >= self.config.failure_threshold;
        let error = if circuit { format!("{}: {error}", BackendError::CircuitOpen) } else { error };
        for route in self.routes.values_mut() { route.fail(&error); }
        let mut status = self.status.lock();
        status.healthy = false;
        status.pid = None;
        status.circuit_open = circuit;
        eprintln!("{}", json!({"component":"agent.backend", "backend":"pi", "phase":"failure", "error":error}));
        status.last_error = Some(error.clone());
        drop(status);
        for (_, reply, _) in self.deferred.drain(..) { let _ = reply.send(Err(error.clone())); }
        for (_, pending) in self.pending.drain() {
            if let Some(reply) = pending.reply { let _ = reply.send(Err(error.clone())); }
        }
        let backoff = self.config.restart_base_ms.saturating_mul(1_u64 << self.failures.saturating_sub(1).min(30))
            .min(self.config.restart_max_ms);
        let mut bytes = [0_u8; 8];
        let _ = getrandom::getrandom(&mut bytes);
        let jitter = u64::from_le_bytes(bytes) % self.config.restart_jitter_ms.saturating_add(1).max(1);
        self.next_start = Instant::now() + Duration::from_millis(backoff.saturating_add(jitter).min(self.config.restart_max_ms));
    }
    fn frame(&mut self, frame: Frame) -> anyhow::Result<()> {
        match frame {
            Frame::Response { id, ok, result, error } => {
                let id = id.ok_or_else(|| anyhow::anyhow!("AgentdProtocolError: uncorrelated response"))?;
                if let Some(pending) = self.pending.remove(&id) {
                    let result = if ok { Ok(result.unwrap_or(Value::Null)) }
                        else { Err(error.map(|e| format!("{}: {}", e.code, e.message)).unwrap_or_else(|| "AgentdResponseError".into())) };
                    if pending.ping {
                        let checked = result.and_then(|v| super::protocol::check_ping(v.clone())
                            .map(|ping| (v, ping)).map_err(|e| e.to_string()));
                        match checked {
                            Ok((value, ping)) => {
                                let mut status = self.status.lock();
                                status.healthy = true;
                                status.agentd_version = Some(ping.version);
                                if let Some(reply) = pending.reply { let _ = reply.send(Ok(value)); }
                            }
                            Err(error) => {
                                if let Some(reply) = pending.reply { let _ = reply.send(Err(error.clone())); }
                                anyhow::bail!(error);
                            }
                        }
                    } else if let Some(reply) = pending.reply { let _ = reply.send(result); }
                }
            }
            Frame::Event { session_id, turn_id, event } => {
                if let Some(route) = self.routes.get_mut(&session_id) { route.accept(turn_id, event)?; }
                // Events after a locally finalized abort are intentionally ignored.
            }
        }
        Ok(())
    }
    fn control(&mut self, command: Control, process: Option<&Process>) -> anyhow::Result<()> {
        self.last_used = Instant::now();
        match command {
            Control::Stop => { self.stopping = true; }
            #[cfg(test)]
            Control::TestExit(_) | Control::TestClose => unreachable!("handled by run"),
            Control::Fail(req, message) => {
                for route in self.routes.values_mut().filter(|r| r.req == req) { route.fail(&message); }
            }
            Control::Register { session, req, translator, stream, timeout, reservation, reply } => {
                if self.routes.contains_key(&session) {
                    let _ = reply.send(Err("AgentdSessionBusy".into()));
                } else if process.is_none() {
                    let _ = reply.send(Err(self.unavailable()));
                } else {
                    self.active.lock().insert(req.clone(), session.clone());
                    let now = Instant::now();
                    self.routes.insert(session.clone(), Route { req, session, active: self.active.clone(), acknowledged: false, started: false, reservation, turn: None, translator, stream,
                        registered_at: now, last_event_at: now,
                        idle_timeout: Duration::from_millis(self.config.turn_idle_timeout_ms),
                        max_duration: timeout, abort_deadline: None,
                        pending: Default::default(), terminal: None, first_error: None });
                    let _ = reply.send(Ok(json!({})));
                }
            }
            Control::Request(command, reply) => {
                if let Some(process) = process {
                    if !self.status.lock().healthy {
                        if self.deferred.len() >= self.config.channel_capacity {
                            let _ = reply.send(Err("AgentdHandshakeQueueFull".into()));
                        } else { self.deferred.push((command, reply, Instant::now())); }
                        return Ok(());
                    }
                    if let Err(e) = self.request(process, command, Some(reply.clone())) {
                        let _ = reply.send(Err(e.to_string()));
                        return Err(e);
                    }
                } else { let _ = reply.send(Err(self.unavailable())); }
            }
            Control::Bind(req, turn, reply) => {
                let route = self.routes.values_mut().find(|r| r.req == req);
                let result = match route {
                    Some(route) if route.turn.as_ref().is_none_or(|id| id == &turn) => {
                        route.turn = Some(turn);
                        route.acknowledged = true;
                        Ok(json!({}))
                    }
                    Some(route) => { route.fail("AgentdTurnMismatch"); Err("AgentdTurnMismatch".into()) }
                    None => Err("AgentdTurnMissing".into()),
                };
                let _ = reply.send(result);
            }
            Control::Cancel(req, reply) => {
                let session = self.active.lock().get(&req).cloned();
                if let Some(session) = session {
                    if let Some(route) = self.routes.get_mut(&session) {
                        route.abort_deadline = Some(Instant::now() + Duration::from_millis(self.config.abort_timeout_ms));
                    }
                    if let Some(process) = process {
                        // Abort response may arrive after turn.completed. Ignore only its result,
                        // using an ordinary reply prevents it being mistaken for a health ping.
                        let (tx, _rx) = std::sync::mpsc::sync_channel(1);
                        self.request(process, Command::Abort(Session { session_id: session }), Some(tx))?;
                    }
                }
                let _ = reply.send(Ok(json!({"accepted":true})));
            }
        }
        Ok(())
    }
    fn unavailable(&self) -> String {
        let status = self.status.lock();
        if status.circuit_open { BackendError::CircuitOpen.to_string() }
        else { status.last_error.clone().unwrap_or_else(|| "AgentdRestarting".into()) }
    }
    fn drain(&mut self) -> bool {
        let mut ready = true;
        self.routes.retain(|_, route| {
            route.tick();
            ready &= route.drain();
            if route.stream.is_finished() { self.active.lock().remove(&route.req); false } else { true }
        });
        ready
    }
    fn deadlines(&mut self, process: Option<&Process>) -> anyhow::Result<()> {
        if let Some(error) = process.and_then(Process::write_error) { anyhow::bail!(error); }
        for route in self.routes.values_mut() {
            if route.abort_deadline.is_some_and(|d| Instant::now() >= d) {
                route.aborted();
                anyhow::bail!("AgentdAbortTimeout: daemon restarted to stop the cancelled turn");
            }
            if let Some(error) = route.timeout_error(Instant::now()) {
                route.fail(error);
                anyhow::bail!(error);
            }
        }
        if self.pending.values().any(|p| p.since.elapsed().as_millis() >= self.config.request_timeout_ms as u128)
            || self.deferred.iter().any(|(_, _, since)| since.elapsed().as_millis() >= self.config.request_timeout_ms as u128) {
            if process.is_some_and(Process::writes_pending) { anyhow::bail!(super::process::WRITER_BACKPRESSURE); }
            anyhow::bail!("AgentdRequestTimeout");
        }
        Ok(())
    }
}
// Also runs when the supervisor future is dropped or its thread unwinds.
impl Drop for State {
    fn drop(&mut self) {
        {
            let mut status = self.status.lock();
            status.healthy = false;
            status.pid = None;
            if !self.stopping || !self.routes.is_empty() {
                status.last_error = Some(super::routes::SUPERVISOR_EXITED.into());
            }
        }
        // Publish failure before waking stream consumers and control callers.
        self.routes.clear();
        self.active.lock().clear();
    }
}
pub async fn run(config: Agentd, mut rx: mpsc::Receiver<Control>, status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>) {
    let now = Instant::now();
    let mut s = State { config, status, active, routes: HashMap::new(), pending: HashMap::new(),
        deferred: Vec::new(), counter: 0, failures: 0, next_start: now, last_ping: now, started: now, last_used: now, stopping: false };
    let mut process: Option<Process> = None;
    let mut ever_started = false;
    let mut idle = false;
    let mut ticker = tokio::time::interval(Duration::from_millis(s.config.supervisor_tick_ms));
    loop {
        if !idle && process.is_none() && !s.status.lock().circuit_open && Instant::now() >= s.next_start {
            match Process::spawn(&s.config) {
                Ok(p) => {
                    { let mut status = s.status.lock(); status.pid = Some(p.pid); if ever_started { status.restarts += 1; } }
                    ever_started = true;
                    s.started = Instant::now();
                    s.last_ping = Instant::now();
                    if let Err(e) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(e.to_string()); }
                    process = Some(p);
                }
                Err(e) => s.fail(e.to_string()),
            }
        }
        let ready = s.drain();
        let outcome: anyhow::Result<()> = tokio::select! {
            command = rx.recv() => {
                match command {
                    #[cfg(test)]
                    Some(Control::TestExit(panic)) => {
                        assert!(!panic, "injected supervisor panic");
                        return;
                    }
                    #[cfg(test)]
                    Some(Control::TestClose) => { rx.close(); Ok(()) }
                    Some(command) => {
                        if idle {
                            idle = false;
                            match Process::spawn(&s.config) {
                                Ok(p) => {
                                    { let mut status = s.status.lock(); status.pid = Some(p.pid); status.restarts += 1; }
                                    s.started = Instant::now();
                                    s.last_ping = Instant::now();
                                    if let Err(error) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(error.to_string()); }
                                    process = Some(p);
                                }
                                Err(e) => s.fail(e.to_string()),
                            }
                        }
                        s.control(command, process.as_ref())
                    }
                    None => break,
                }
            }
            frame = async { match &mut process { Some(p) => p.incoming.recv().await, None => std::future::pending().await } }, if ready => {
                match frame { Some(Ok(frame)) => s.frame(frame), Some(Err(e)) => Err(e), None => Err(anyhow::anyhow!("AgentdEof")) }
            }
            _ = ticker.tick() => {
                let deadlines = s.deadlines(process.as_ref());
                if let Some(p) = &mut process {
                    if p.exited().unwrap_or(true) { Err(anyhow::anyhow!("AgentdExited")) }
                    else if deadlines.is_err() { deadlines }
                    else if ready && s.last_ping.elapsed().as_millis() >= s.config.ping_interval_ms as u128 {
                        s.last_ping = Instant::now();
                        s.request(p, Command::Ping(Empty {}), None)
                    } else {
                        if s.status.lock().healthy && s.started.elapsed().as_millis() >= s.config.stable_reset_ms as u128 { s.failures = 0; }
                        Ok(())
                    }
                } else { deadlines }
            }
        };
        let outcome = outcome.and_then(|()| {
            if s.status.lock().healthy {
                if let Some(p) = process.as_ref() {
                    for (command, reply, _) in std::mem::take(&mut s.deferred) {
                        if let Err(error) = s.request(p, command, Some(reply.clone())) {
                            let _ = reply.send(Err(error.to_string()));
                            return Err(error);
                        }
                    }
                }
            }
            Ok(())
        });
        if let Err(error) = outcome {
            s.fail(error.to_string());
            if let Some(mut p) = process.take() { p.stop().await; }
        }
        if s.stopping {
            for route in s.routes.values_mut() { route.fail("AgentdShutdown"); }
            if let Some(mut p) = process.take() { p.stop().await; }
            // Delivery is cancellable by dropping the receiver; keep draining retained events.
            while !s.routes.is_empty() { s.drain(); ticker.tick().await; }
            break;
        }
        if process.is_some() && s.routes.is_empty() && s.pending.is_empty()
            && s.last_used.elapsed().as_millis() >= s.config.idle_ms as u128 {
            if let Some(mut p) = process.take() { p.stop().await; }
            let mut status = s.status.lock(); status.pid = None; status.healthy = false;
            idle = true;
        }
    }
    let mut status = s.status.lock(); status.pid = None; status.healthy = false;
}
use super::{protocol::Command, supervisor, translate::Translator};
use super::super::{config::Agentd, stream::Mailbox, BackendStatus};
use std::{sync::{Arc, mpsc}, time::{Duration, Instant}};
use parking_lot::Mutex;
use serde_json::Value;
pub type Reply = mpsc::SyncSender<Result<Value, String>>;
pub enum Control {
    Request(Command, Reply),
    Register { session: String, req: String, translator: Translator, stream: Arc<Mailbox>, timeout: Duration, reservation: (Arc<Mutex<std::collections::HashSet<String>>>, String), reply: Reply },
    Cancel(String, Reply),
    Bind(String, String, Reply),
    Fail(String, String),
    Stop,
    #[cfg(test)]
    TestExit(bool),
    #[cfg(test)]
    TestClose,
}
pub struct Client {
    pub config: Agentd,
    tx: tokio::sync::mpsc::Sender<Control>,
    pub status: Arc<Mutex<BackendStatus>>,
    pub active: Arc<Mutex<std::collections::HashMap<String, String>>>,
}
impl Client {
    pub fn new(config: Agentd) -> anyhow::Result<Arc<Self>> {
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
        let (tx, rx) = tokio::sync::mpsc::channel(config.channel_capacity);
        let client = Arc::new(Self { config: config.clone(), tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))), active: Arc::new(Mutex::new(Default::default())) });
        let status = client.status.clone();
        let active = client.active.clone();
        std::thread::Builder::new().name("agentd-supervisor".into()).spawn(move || {
            runtime.block_on(supervisor::run(config, rx, status, active));
        })?;
        Ok(client)
    }
    pub fn send(&self, mut command: Control) -> anyhow::Result<()> {
        let deadline = Instant::now() + Duration::from_millis(self.config.request_timeout_ms);
        loop {
            match self.tx.try_send(command) {
                Ok(()) => return Ok(()),
                Err(tokio::sync::mpsc::error::TrySendError::Full(c)) => command = c,
                Err(_) => anyhow::bail!("AgentdSupervisorStopped"),
            }
            anyhow::ensure!(Instant::now() < deadline, "AgentdControlTimeout");
            std::thread::sleep(Duration::from_millis(self.config.control_poll_ms));
        }
    }
    pub fn call(&self, command: Command) -> anyhow::Result<Value> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Request(command, tx))?;
        self.wait(rx)
    }
    pub fn wait(&self, rx: mpsc::Receiver<Result<Value, String>>) -> anyhow::Result<Value> {
        // Budget queue/serialization separately from the actor's request deadline,
        // so its specific write/response error wins over the caller's fallback.
        let timeout = self.config.request_timeout_ms.saturating_mul(2)
            .saturating_add(self.config.supervisor_tick_ms.saturating_mul(2));
        rx.recv_timeout(Duration::from_millis(timeout)).map_err(|error| {
            let status = self.status.lock();
            let message = if !status.healthy { status.last_error.clone() } else { None };
            anyhow::anyhow!(message.unwrap_or_else(|| match error {
                mpsc::RecvTimeoutError::Disconnected => "AgentdSupervisorStopped".into(),
                mpsc::RecvTimeoutError::Timeout => "AgentdRequestTimeout".into(),
            }))
        })?.map_err(anyhow::Error::msg)
    }
    pub fn cancel(&self, req: &str) -> anyhow::Result<()> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Cancel(req.into(), tx))?;
        self.wait(rx).map(|_| ())
    }
    pub fn stop(&self) { let _ = self.send(Control::Stop); }
}
impl Drop for Client { fn drop(&mut self) { let _ = self.tx.try_send(Control::Stop); } }

import type { AgentSession } from "@earendil-works/pi-coding-agent";
import type { Config } from "../config/schema.ts";
import { DaemonError } from "../protocol/errors.ts";
import type { SessionOptions } from "../protocol/schema.ts";

export function profileTools(config: Config, profile: string): string[] {
  if (!Object.hasOwn(config.toolProfiles, profile)) {
    throw new DaemonError("TOOL_PROFILE_NOT_FOUND", "Unknown tool profile");
  }
  return config.toolProfiles[profile];
}
export function checkTools(session: AgentSession, tools: string[]): void {
  const known = new Set(session.getAllTools().map((tool) => tool.name));
  if (tools.some((name) => !known.has(name))) {
    throw new DaemonError("TOOL_PROFILE_UNAVAILABLE", "Profile contains tools unavailable in this session; reopen required");
  }
}
export function activateTools(session: AgentSession, tools: string[]): void {
  checkTools(session, tools);
  session.setActiveToolsByName(tools);
  const active = session.getActiveToolNames();
  if (active.length !== tools.length || tools.some((name) => !active.includes(name))) {
    throw new DaemonError("TOOL_PROFILE_UNAVAILABLE", "SDK cannot activate the requested tool profile");
  }
}
export async function configureSession(session: AgentSession, config: Config, options: SessionOptions): Promise<void> {
  const tools = options.toolProfile === undefined ? undefined : profileTools(config, options.toolProfile);
  if (tools) checkTools(session, tools);
  const model = options.model && session.modelRuntime.getModel(options.model.provider, options.model.id);
  if (options.model && !model) throw new DaemonError("MODEL_NOT_FOUND", "Requested model does not exist");
  if (model) {
    try { await session.setModel(model, { persist: false }); }
    catch { throw new DaemonError("MODEL_CONFIGURE_FAILED", "SDK could not select the requested model"); }
  }
  if (options.thinkingLevel !== undefined) session.setThinkingLevel(options.thinkingLevel, { persist: false });
  if (tools) activateTools(session, tools);
}
import { mkdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import {
  createAgentSession, DefaultResourceLoader, SessionManager, SettingsManager,
  type ExtensionFactory,
} from "@earendil-works/pi-coding-agent";
import type { Config } from "../config/schema.ts";
import type { Models } from "../models/runtime.ts";
import type { SessionOptions } from "../protocol/schema.ts";
import { activateTools, profileTools } from "./options.ts";
import { DaemonError } from "../protocol/errors.ts";

export async function createSession(
  config: Config, models: Models, factories: ExtensionFactory[], sessionId?: string, requestedCwd?: string, options: SessionOptions = {},
) {
  const runtime = models.runtime;
  const tools = profileTools(config, options.toolProfile ?? config.defaultToolProfile);
  mkdirSync(config.sessionDir, { recursive: true });
  const cwd = resolve(requestedCwd ?? process.cwd());
  let manager: SessionManager;
  if (sessionId) {
    // Exact lookup, never treat an untrusted session id as a filesystem path.
    if (!/^[a-zA-Z0-9-]+$/.test(sessionId)) throw new DaemonError("INVALID_SESSION_ID", "Invalid session id");
    const path = (await SessionManager.listAll(config.sessionDir)).find((info) => info.id === sessionId)?.path;
    if (!path) throw new DaemonError("SESSION_NOT_FOUND", "Persisted session not found");
    manager = SessionManager.open(path, config.sessionDir, requestedCwd ? cwd : undefined);
  } else manager = SessionManager.create(cwd, config.sessionDir);
  try {
    if (!statSync(manager.getCwd()).isDirectory()) throw new Error();
  } catch {
    throw new DaemonError("INVALID_CWD", "Working directory does not exist");
  }
  const model = runtime.getModel((options.model ?? config.defaultModel).provider, (options.model ?? config.defaultModel).id);
  if (!model) throw new DaemonError("MODEL_NOT_FOUND", "Configured default model does not exist");
  const settingsManager = SettingsManager.inMemory({
    compaction: config.compaction, retry: config.retry, cacheWarming: "off",
  });
  const agentDir = join(config.sessionDir, ".resources");
  const resourceLoader = new DefaultResourceLoader({
    cwd: manager.getCwd(), agentDir, settingsManager,
    // Only host-assembled executable extensions. Standard AGENTS.md/skills still load.
    noExtensions: true, noThemes: true,
    extensionFactories: config.extensions.enabled ? factories : [],
  });
  await resourceLoader.reload();
  const { session } = await createAgentSession({
    cwd: manager.getCwd(), agentDir, model, modelRuntime: runtime,
    thinkingLevel: options.thinkingLevel ?? config.thinkingLevel,
    // Register the configured universe so idle profile changes can enable tools.
    tools: [...new Set(Object.values(config.toolProfiles).flat())],
    settingsManager, sessionManager: manager, resourceLoader,
  });
  try {
    await session.bindExtensions({ mode: "rpc" });
    activateTools(session, tools);
    return session;
  } catch (error) {
    session.dispose();
    throw error;
  }
}
import { randomUUID } from "node:crypto";
import type { AgentSession, ExtensionFactory } from "@earendil-works/pi-coding-agent";
import type { Config } from "../config/schema.ts";
import { EventMapper } from "../events/mapper.ts";
import type { Models } from "../models/runtime.ts";
import type { ProtocolEvent, TurnStatus } from "../protocol/events.ts";
import { DaemonError, publicError } from "../protocol/errors.ts";
import type { SessionOptions, ImageAttachment } from "../protocol/schema.ts";
import { configureSession } from "./options.ts";
import { imagesForPrompt } from "./attachments.ts";
import { createSession } from "./create.ts";

interface Run {
  id: string;
  done: Promise<void>;
  mapper: EventMapper;
  stopped?: TurnStatus;
}
interface Entry {
  session: AgentSession;
  run?: Run;
  configuring?: Promise<void>;
  toolProfile: string;
  closing?: Promise<void>;
  idle?: NodeJS.Timeout;
  lastUsed: number;
  queueReservations: number;
}

export class SessionRegistry {
  private readonly entries = new Map<string, Entry>();
  private readonly opening = new Set<string>();
  private pendingOpens = 0;
  private stopped = false;
  constructor(
    private readonly config: () => Config,
    private readonly models: Models,
    private readonly factories: ExtensionFactory[],
    private readonly emit: (event: ProtocolEvent) => void,
  ) {}
  get size(): number { return this.entries.size; }
  async open(sessionId?: string, cwd?: string, options: SessionOptions = {}) {
    if (this.stopped) throw new DaemonError("SHUTTING_DOWN", "Daemon is shutting down");
    if (sessionId && (this.entries.has(sessionId) || this.opening.has(sessionId))) {
      throw new DaemonError("SESSION_ALREADY_OPEN", "Session is already open");
    }
    if (this.size + this.pendingOpens >= this.config().maxSessions) {
      throw new DaemonError("SESSION_LIMIT", "Maximum concurrent sessions reached");
    }
    this.pendingOpens++;
    if (sessionId) this.opening.add(sessionId);
    try {
      const config = this.config();
      const session = await createSession(config, this.models, this.factories, sessionId, cwd, options);
      if (this.stopped) {
        session.dispose();
        throw new DaemonError("SHUTTING_DOWN", "Daemon is shutting down");
      }
      const id = session.sessionId;
      const entry: Entry = { session, toolProfile: options.toolProfile ?? config.defaultToolProfile, lastUsed: Date.now(), queueReservations: 0 };
      this.entries.set(id, entry);
      this.armIdle(id, entry);
      return { sessionId: id, resumed: !!sessionId, messageCount: session.messages.length,
        model: { provider: session.model!.provider, id: session.model!.id },
        thinkingLevel: session.thinkingLevel, toolProfile: entry.toolProfile, tools: session.getActiveToolNames(),
        reopenRequired: session.modelRuntime !== this.models.runtime };
    } finally {
      this.pendingOpens--;
      if (sessionId) this.opening.delete(sessionId);
    }
  }
  private get(id: string): Entry {
    const entry = this.entries.get(id);
    if (!entry) throw new DaemonError("SESSION_NOT_FOUND", "Session is not open");
    if (entry.closing) throw new DaemonError("SESSION_CLOSING", "Session is closing");
    return entry;
  }
  async configure(id: string, options: SessionOptions) {
    const entry = this.get(id);
    if (entry.run || entry.configuring || !entry.session.isIdle) throw new DaemonError("SESSION_BUSY", "Session is busy");
    clearTimeout(entry.idle);
    entry.configuring = configureSession(entry.session, this.config(), options);
    try {
      await entry.configuring;
      entry.toolProfile = options.toolProfile ?? entry.toolProfile;
      return { sessionId: id, model: entry.session.model && {
        provider: entry.session.model.provider, id: entry.session.model.id },
        thinkingLevel: entry.session.thinkingLevel, toolProfile: entry.toolProfile,
        tools: entry.session.getActiveToolNames() };
    } finally {
      entry.configuring = undefined;
      entry.lastUsed = Date.now();
      if (!entry.closing && !this.stopped) this.armIdle(id, entry);
    }
  }
  prompt(id: string, text: string, attachments: ImageAttachment[] = []) {
    const entry = this.get(id);
    if (entry.run || entry.configuring) throw new DaemonError("SESSION_BUSY", "Use steer or followUp while a prompt is running");
    const images = imagesForPrompt(attachments, this.config());
    if (images.length && !entry.session.model?.input.includes("image")) {
      throw new DaemonError("MODEL_IMAGES_UNSUPPORTED", "Selected model does not accept images");
    }
    clearTimeout(entry.idle);
    const mapper = new EventMapper(id, randomUUID(), this.emit);
    const run: Run = { id: mapper.turnId, mapper, done: Promise.resolve() };
    entry.run = run;
    // Reserve synchronously; start after the command returns to permit immediate abort.
    run.done = Promise.resolve().then(() => this.execute(id, entry, run, text, images));
    return { turnId: run.id, disposition: "started" };
  }
  private async execute(id: string, entry: Entry, run: Run, text: string, images: ImageAttachment[]): Promise<void> {
    const { session } = entry;
    run.mapper.emit({ event: "turn.started" });
    const { turnIdleTimeoutMs, turnMaxMs } = this.config();
    let idleTimer: NodeJS.Timeout;
    let maxTimer: NodeJS.Timeout | undefined;
    const expire = (code: "TURN_IDLE_TIMEOUT" | "TURN_MAX_TIMEOUT") => {
      if (run.stopped) return;
      run.stopped = "timeout";
      clearTimeout(idleTimer);
      clearTimeout(maxTimer);
      run.mapper.error(code, code === "TURN_IDLE_TIMEOUT" ? "本轮长时间未收到事件，已取消。" : "本轮超过最长运行时间，已取消。");
      session.clearQueue();
      void session.abort().catch(() => undefined);
    };
    const armIdle = () => {
      clearTimeout(idleTimer);
      if (!run.stopped) idleTimer = setTimeout(() => expire("TURN_IDLE_TIMEOUT"), turnIdleTimeoutMs);
    };
    const unsubscribe = session.subscribe((event) => {
      armIdle(); // All SDK events count, including tool progress and retry/compaction events.
      run.mapper.accept(event, !!run.stopped);
    });
    armIdle();
    if (turnMaxMs > 0) maxTimer = setTimeout(() => expire("TURN_MAX_TIMEOUT"), turnMaxMs);
    try {
      if (!run.stopped) {
        await session.prompt(text, {
          expandPromptTemplates: false, images,
          preflightResult: () => {
            if (run.stopped) throw new DaemonError("TURN_CANCELLED", "Turn was cancelled during preparation");
          },
        });
      }
    } catch (error) {
      if (!run.stopped) {
        run.mapper.status = "error";
        const safe = publicError(error);
        run.mapper.error(safe.code, safe.message);
      }
    } finally {
      clearTimeout(idleTimer!);
      clearTimeout(maxTimer);
      unsubscribe();
      session.clearQueue();
      entry.run = undefined;
      entry.lastUsed = Date.now();
      run.mapper.emit({ event: "turn.completed", status: run.stopped ?? run.mapper.status });
      if (!entry.closing && !this.stopped) this.armIdle(id, entry);
    }
  }
  async queue(id: string, text: string, method: "steer" | "followUp") {
    const entry = this.get(id);
    const run = entry.run;
    if (!run || run.stopped) throw new DaemonError("SESSION_NOT_RUNNING", "No active turn accepts queued input");
    if (!entry.session.isStreaming) throw new DaemonError("TURN_NOT_READY", "Turn is still preparing");
    if (entry.session.pendingMessageCount + entry.queueReservations >= this.config().maxQueuedMessages) {
      throw new DaemonError("QUEUE_LIMIT", "Maximum queued messages reached");
    }
    entry.queueReservations++;
    try {
      const disposition = await entry.session[method](text);
      return { turnId: run.id, disposition };
    } finally {
      entry.queueReservations--;
      if (entry.run !== run || run.stopped) entry.session.clearQueue();
    }
  }
  async abort(id: string): Promise<{ aborted: boolean }> {
    const entry = this.get(id);
    const run = entry.run;
    if (!run) return { aborted: false };
    run.stopped ??= "aborted";
    entry.session.clearQueue();
    await entry.session.abort();
    await run.done;
    return { aborted: true };
  }
  async wait(id: string): Promise<void> { await this.get(id).run?.done; }
  async close(id: string): Promise<void> {
    const entry = this.entries.get(id);
    if (!entry) throw new DaemonError("SESSION_NOT_FOUND", "Session is not open");
    if (entry.closing) return entry.closing;
    clearTimeout(entry.idle);
    entry.closing = (async () => {
      try {
        await entry.configuring?.catch(() => undefined);
        if (entry.run) {
          entry.run.stopped ??= "aborted";
          entry.session.clearQueue();
          await entry.session.abort();
          await entry.run?.done;
        }
      } finally {
        entry.session.dispose();
        this.entries.delete(id);
      }
    })();
    return entry.closing;
  }
  private armIdle(id: string, entry: Entry): void {
    clearTimeout(entry.idle);
    const remaining = Math.max(1, this.config().idleTimeoutMs - (Date.now() - entry.lastUsed));
    entry.idle = setTimeout(() => { void this.close(id).catch(() => undefined); }, remaining);
    entry.idle.unref();
  }
  reopenRequired(): string[] {
    return [...this.entries].filter(([, entry]) => entry.session.modelRuntime !== this.models.runtime)
      .map(([id]) => id);
  }
  refreshConfig(): void {
    for (const [id, entry] of this.entries) if (!entry.run && !entry.configuring && !entry.closing) this.armIdle(id, entry);
  }
  async shutdown(): Promise<void> {
    this.stopped = true;
    await Promise.all([...this.entries.keys()].map((id) => this.close(id)));
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { Value } from "typebox/value";
import { readFileSync } from "node:fs";
import { fauxAssistantMessage } from "@earendil-works/pi-ai";
